mapper.select:
SELECT a.* from application a where a.id in( select r.app_id from ( SELECT * FROM role r where r.status =1 )r join ( SELECT DISTINCT dr.role_id from depts_roles dr where dr.dept_id in
#{item}
union SELECT DISTINCT gr.role_id from groups_roles gr join groups_users gu on gr.group_id = gu.group_id and gu.user_id = #{userId} union SELECT DISTINCT ur.role_id from users_roles ur where ur.user_id=#{userId}
)rid on r.id = rid.role_id )

select u.*, dr.role_id FROM `user` u join DEPTS_ROLES dr on u.dept_id = dr.DEPT_ID where u.dept_id in
#{item}
union
select u.* from ( select distinct u.*, gr.role_id FROM `user` u join groups_users gu on gu.user_id = u.id join groups_roles gr on gu.group_id = gr.group_id where u.status = 1 union select u.*, ur.role_id FROM `user` u join users_roles ur on u.id = ur.user_id where u.status = 1 ) u join role r on u.role_id = r.id and r.status = 1 and r.type = 0 join application app on r.app_id = app.id and app.status = 1 and app.code =#{appCode}
